 ```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #0b0f19;
    color: #e5e7eb;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    gap: 16px;
  }
  h1 { margin: 0; font-size: 1.5rem; color: #93c5fd; }
  #sim {
    width: 600px;
    height: 600px;
    background: #1f2937;
    border-radius: 12px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.5);
    cursor: crosshair;
    touch-action: none;
  }
  .controls { display: flex; gap: 12px; }
  button {
    padding: 10px 20px;
    font-size: 1rem;
    border: none;
    border-radius: 8px;
    background: #2563eb;
    color: white;
    cursor: pointer;
    transition: background 0.15s, transform 0.05s;
  }
  button:hover { background: #3b82f6; }
  button:active { transform: scale(0.96); }
  #clear { background: #dc2626; }
  #clear:hover { background: #ef4444; }
  #play { background: #059669; }
  #play:hover { background: #10b981; }
</style>
</head>
<body>
  <h1>Bouncing Ball Playground</h1>
  <canvas id="sim"></canvas>
  <div class="controls">
    <button id="drop" type="button">Drop</button>
    <button id="play" type="button">Pause</button>
    <button id="clear" type="button">Clear</button>
  </div>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const GRAVITY = 0.5;
  const RESTITUTION = 0.8;

  let balls = [];
  let playing = true;
  let rafId = null;

  function resize() {
    const rect = canvas.getBoundingClientRect();
    canvas.width = Math.max(400, Math.floor(rect.width));
    canvas.height = Math.max(400, Math.floor(rect.height));
  }

  function defaultRadius() {
    return 10 + Math.random() * 10;
  }

  function addBall(x, y, vx = 0, vy = 0, r) {
    const radius = r == null ? defaultRadius() : +r;
    const ball = {
      x: +x,
      y: +y,
      vx: +vx,
      vy: +vy,
      r: radius,
      hue: Math.random() * 360
    };
    ball.x = Math.max(ball.r, Math.min(window.sim.w - ball.r, ball.x));
    ball.y = Math.max(ball.r, Math.min(window.sim.h - ball.r, ball.y));
    balls.push(ball);
    draw();
    return ball;
  }

  function clear() {
    balls = [];
    draw();
  }

  function step(dt = 1) {
    dt = +dt || 1;
    const w = window.sim.w;
    const h = window.sim.h;
    for (const b of balls) {
      b.vy += GRAVITY * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx *= -RESTITUTION;
      } else if (b.x + b.r > w) {
        b.x = w - b.r;
        b.vx *= -RESTITUTION;
      }

      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy *= -RESTITUTION;
      } else if (b.y + b.r > h) {
        b.y = h - b.r;
        b.vy *= -RESTITUTION;
      }
    }
    draw();
  }

  function ballsSnapshot() {
    return balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r }));
  }

  function draw() {
    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let i = 0; i < canvas.width; i += 50) {
      ctx.moveTo(i, 0);
      ctx.lineTo(i, canvas.height);
    }
    for (let j = 0; j < canvas.height; j += 50) {
      ctx.moveTo(0, j);
      ctx.lineTo(canvas.width, j);
    }
    ctx.stroke();

    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      const gradient = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1,
        b.x, b.y, b.r
      );
      gradient.addColorStop(0, `hsl(${b.hue}, 100%, 75%)`);
      gradient.addColorStop(1, `hsl(${b.hue}, 80%, 55%)`);
      ctx.fillStyle = gradient;
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.4)';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }
  }

  function loop() {
    if (!playing) return;
    step(1);
    rafId = requestAnimationFrame(loop);
  }

  window.sim = {
    get w() { return canvas.width; },
    get h() { return canvas.height; },
    balls: ballsSnapshot,
    addBall,
    clear,
    step
  };

  const dropBtn = document.getElementById('drop');
  const playBtn = document.getElementById('play');
  const clearBtn = document.getElementById('clear');

  dropBtn.addEventListener('click', () => {
    addBall(window.sim.w / 2, 50, (Math.random() - 0.5) * 6, 0);
  });

  playBtn.addEventListener('click', () => {
    playing = !playing;
    playBtn.textContent = playing ? 'Pause' : 'Play';
    if (playing) loop();
    else cancelAnimationFrame(rafId);
  });

  clearBtn.addEventListener('click', () => {
    clear();
  });

  canvas.addEventListener('pointerdown', (e) => {
    const rect = canvas.getBoundingClientRect();
    addBall(
      e.clientX - rect.left,
      e.clientY - rect.top,
      (Math.random() - 0.5) * 8,
      (Math.random() - 0.5) * 8
    );
  });

  window.addEventListener('resize', resize);

  resize();
  draw();
  loop();
})();
</script>
</body>
</html>
